    if (hs.length) {
      const bad = structuredClone(hs);
      bad[0].oldStart += 1;
      assert.throws(() => applyHunks(a, bad), /hunk 0 does not apply/);
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// coordinate checks
assert.deepEqual(unifiedHunks(['a'], ['n', 'a'], { context: 0 }), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+n'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['b'], { context: 0 }), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-a'] }]);
assert.deepEqual(unifiedHunks([], ['x']), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] }]);

